import numpy as np
# invalid input: a negative shell count has no basis and must raise ValueError
n_max = -1
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: oscillator_basis(n_max)), target)

